  Placement Plan(int total){var u=original.unitTypes;var p=new Placement{agents=total,centers=new Vector2[u.Length],sizes=new Vector3[u.Length],densities=new float[u.Length]};if(u.Length!=2||u[0].teamId!=0||u[1].teamId!=1){p.reason="Requires two original teams in stable unit order; do not silently substitute roster.";return p;}var nav=m.TerrainNavigation;var candidates=new List<Vector2>[2];
   for(int t=0;t<2;t++){var sp=u[t].spawnConfig;p.densities[t]=sp.ResolveDensity();p.sizes[t]=SpawnConfig.ResolveSpawnSize(total/2,p.densities[t],sp.ResolveSpawnSize().z/sp.ResolveSpawnSize().x,Vector3.zero);candidates[t]=new List<Vector2>();for(int z=0;z<nav.ResolutionZ;z+=4)for(int x=0;x<nav.ResolutionX;x+=4){var v=nav.CellCenter(z*nav.ResolutionX+x);if(t==0?v.x>=-8:v.x<=8)continue;if(nav.IsFootprintWalkable(v,new Vector2(p.sizes[t].x,p.sizes[t].z)))candidates[t].Add(v);} }
   foreach(var a in candidates[0].OrderBy(v=>Mathf.Abs(v.y)+Mathf.Abs(v.x)))foreach(var b in candidates[1].OrderBy(v=>Mathf.Abs(v.y)+Mathf.Abs(v.x))){if(b.x-a.x<(p.sizes[0].x+p.sizes[1].x)*.5f+16)continue;if(!nav.AreConnected(a,b))continue;p.centers[0]=a;p.centers[1]=b;p.fits=true;p.reason="Conservative full-footprint navigation checks; original effective density/aspect, two disjoint connected formations.";return p;}p.reason="No legal pair in the documented 4-cell-stride placement search. Not proof no other layout exists; no density increase or terrain removal permitted.";return p;
  }
  long Buffers(){var seen=new HashSet<ComputeBuffer>();Action<object> scan=o=>{foreach(var f in o.GetType().GetFields(BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic)){var v=f.GetValue(o);if(v is ComputeBuffer b)seen.Add(b);if(v is ComputeBuffer[] a)foreach(var q in a)if(q!=null)seen.Add(q);}};scan(m.Buffers);scan(m.Buffers.combatBuffers);return seen.Where(x=>x!=null).Sum(x=>(long)x.count*x.stride);}
  [UnityTest,Timeout(240000)]public IEnumerator CapacityGeometryPreflight(){m.PauseBattle();var nav=m.TerrainNavigation;var pos=new Vector2[m.Buffers.AgentCount];var team=new int[pos.Length];m.Buffers.agentPositionReadBuffer.GetData(pos);m.Buffers.combatBuffers.teamIdBuffer.GetData(team);var r=new Inventory{gpu=SystemInfo.graphicsDeviceName,api=SystemInfo.graphicsDeviceType.ToString(),graphicsMB=SystemInfo.graphicsMemorySize,agents=pos.Length,gridCells=m.Buffers.GridCellCount,maxPerCell=m.Buffers.MaxAgentsPerCell,flowCells=m.Buffers.FlowCellCount,types=m.Buffers.UnitTypeCount,teams=m.Buffers.TeamCount,origin=nav.Origin,resolutionX=nav.ResolutionX,resolutionZ=nav.ResolutionZ,cell=nav.CellSize,navClearance=nav.Clearance,currentCoreBufferBytes=Buffers(),validTeam0=Enumerable.Range(0,pos.Length).Count(i=>team[i]==0&&nav.IsWalkable(pos[i]))};foreach(int n in new[]{2048,50000}){r.placements.Add(Plan(n));yield return null;}File.WriteAllText(Path.Combine(output,"capacity-geometry.json"),JsonUtility.ToJson(r,true));Debug.Log("P9_STAGE capacity-geometry "+JsonUtility.ToJson(r));}
