  IEnumerator Measure(int total){Assert.False(Application.isBatchMode);yield return Resolution();QualitySettings.vSyncCount=0;Application.targetFrameRate=-1;
   if(total!=2048){var p=Plan(total);File.WriteAllText(Path.Combine(output,"placement.json"),JsonUtility.ToJson(p,true));Assert.True(p.fits,p.reason);var sc=Clone(original);sc.unitTypes=new UnitTypeConfig[2];for(int i=0;i<2;i++){var u=Clone(original.unitTypes[i]);u.spawnConfig=Clone(u.spawnConfig);u.spawnConfig.unitCount=total/2;u.spawnConfig.spawnCenter=new Vector3(p.centers[i].x,0,p.centers[i].y);u.spawnConfig.spawnSize=p.sizes[i];sc.unitTypes[i]=u;}m.scenarioConfig=sc;}
   var cam=m.cullingCamera;Assert.NotNull(cam);Vector3 cp=new Vector3(0,400,-260);Quaternion cq=Quaternion.LookRotation(-cp);int rendered=0,last=-1;Action<Camera> observe=v=>{if(v==cam&&v.targetTexture==null&&last!=Time.frameCount){last=Time.frameCount;rendered++;}};Camera.CameraCallback post=v=>observe(v);Action<ScriptableRenderContext,Camera> srp=(ctx,v)=>observe(v);Camera.onPostRender+=post;RenderPipelineManager.endCameraRendering+=srp;
   var main=ProfilerRecorder.StartNew(ProfilerCategory.Internal,"Main Thread",1);var ft=new FrameTiming[1];ulong stamp=0;
   var commands=new List<string>{"window,mode,cache,selected,observed_ms,readback_ms,plan_ms,upload_ms,executing,blocked"};var summaries=new List<string>{"window,mode,agents,samples,camera_frames,alive,groups,local_bytes,core_buffer_bytes,global_dispatches,local_dispatches,overflow_end,sentinel,width,height,gpu_valid_samples,visible_instances_end"};int window=0;
   try{foreach(string mode in new[]{"off","empty","selected4","selected1000","selected1000","selected4","empty","off"}){window++;m.PauseBattle();m.ResetScenario();c.RebuildArmyStates();Assert.AreEqual(total,m.Buffers.AgentCount);Assert.True(c.IssueOrder(ArmyOrder.Hold(0)));Assert.True(c.IssueOrder(ArmyOrder.Hold(1)));m.PauseBattle();cam.transform.SetPositionAndRotation(cp,cq);yield return Frames(5);if(mode!="off")Assert.True(m.TryEnableLocalOrderPrototype(out var err),err);
    var pipeline=(ComputePipelineOrchestrator)typeof(MassEngineManager).GetField("pipelineOrchestrator",Private).GetValue(m);var field=typeof(ComputePipelineOrchestrator).GetField("dispatchListener",Private);var old=field.GetValue(pipeline);var counter=new Counter();field.SetValue(pipeline,counter);
    try{m.StartBattle();if(mode.StartsWith("selected")){int k=mode=="selected4"?4:1000;var positions=new Vector2[total];var teams=new int[total];m.Buffers.agentPositionReadBuffer.GetData(positions);m.Buffers.combatBuffers.teamIdBuffer.GetData(teams);var ids=Enumerable.Range(0,total).Where(i=>teams[i]==0&&m.TerrainNavigation.IsWalkable(positions[i])).Take(k).ToArray();Assert.AreEqual(k,ids.Length,"Not enough physically valid members; do not lower selected count");var sw=System.Diagnostics.Stopwatch.StartNew();var receipt=m.LocalOrders.Submit(m.LocalOrders.Epoch,0,window,ids,LocalOrderKind.Hold,Vector2.zero);double deadline=Time.realtimeSinceStartupAsDouble+120;while((receipt.Status==LocalOrderStatus.AwaitingSnapshot||receipt.GpuExecutingMembers==0)&&Time.realtimeSinceStartupAsDouble<deadline){if(receipt.Status==LocalOrderStatus.Rejected)Assert.Fail(receipt.Error);yield return null;}Assert.Greater(receipt.GpuExecutingMembers,0,receipt.Error);Assert.AreEqual(k,receipt.SubmittedMembers);commands.Add(string.Join(",",window,mode,"existing-cache-first-use-not-cold-ABA",k,F(sw.Elapsed.TotalMilliseconds),F(receipt.ReadbackMilliseconds),F(receipt.PlanMilliseconds),F(receipt.UploadMilliseconds),receipt.GpuExecutingMembers,receipt.GpuBlockedMembers));File.WriteAllLines(Path.Combine(output,"commands.csv"),commands);}
     m.StartBattle();double warm=Time.realtimeSinceStartupAsDouble+3;while(Time.realtimeSinceStartupAsDouble<warm){cam.transform.SetPositionAndRotation(cp,cq);yield return null;}counter.counts.Clear();int before=rendered,validGpu=0;var raw=new List<Sample>(4096);double start=Time.realtimeSinceStartupAsDouble,prev=start;
     while(Time.realtimeSinceStartupAsDouble-start<5){cam.transform.SetPositionAndRotation(cp,cq);FrameTimingManager.CaptureFrameTimings();yield return null;double now=Time.realtimeSinceStartupAsDouble;bool fresh=FrameTimingManager.GetLatestTimings(1,ft)>0&&ft[0].frameStartTimestamp>stamp&&ft[0].gpuFrameTime>0;if(fresh){stamp=ft[0].frameStartTimestamp;validGpu++;}raw.Add(new Sample{frame=Time.frameCount,wall=(now-prev)*1000,main=main.Valid?main.LastValue:-1,gpu=fresh?ft[0].gpuFrameTime:0,fresh=fresh,memory=UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong(),groups=m.LocalOrders?.ActiveGroups??0});prev=now;}
     m.PauseBattle();int[] hp=new int[total],stats=new int[4];m.Buffers.combatBuffers.hpReadBuffer.GetData(hp);m.Buffers.spatialHashStatsBuffer.GetData(stats);Assert.AreEqual(MassGpuBufferManager.DeviceResetSentinel,stats[3]);Assert.AreEqual(total,hp.Count(x=>x>0),"Standing comparison must not silently become a casualty comparison");Assert.GreaterOrEqual(rendered-before,(raw.Count)/2);Assert.AreEqual(counter.Get("ClearPendingDamage"),counter.Get("SimulateCombatAndAccumulateDamage"));int locals=counter.counts.Where(x=>x.Key.StartsWith("SimulateLocal")).Sum(x=>x.Value);if(mode.StartsWith("selected"))Assert.Greater(locals,0);else Assert.AreEqual(0,locals);
     uint visible=0;foreach(var args in (ComputeBuffer[])typeof(MassGpuBufferManager).GetField("drawArgsBuffers",Private).GetValue(m.Buffers)){if(args==null)continue;var values=new uint[5];args.GetData(values);visible+=values[1];}Assert.Greater(visible,0,"Camera callbacks alone do not prove visible units");
     File.WriteAllLines(Path.Combine(output,"window-"+window.ToString("00")+"-"+mode+".csv"),new[]{"frame,wall_ms,main_ns,gpu_ms,gpu_new_timestamp,allocated_bytes,local_groups"}.Concat(raw.Select(x=>string.Join(",",x.frame,F(x.wall),x.main,x.fresh?F(x.gpu):"",x.fresh?1:0,x.memory,x.groups))));summaries.Add(string.Join(",",window,mode,total,raw.Count,rendered-before,hp.Count(x=>x>0),m.LocalOrders?.ActiveGroups??0,m.LocalOrders?.GpuBytes??0,Buffers(),counter.Get("SimulateCombatAndAccumulateDamage"),locals,stats[0],stats[3],Screen.width,Screen.height,validGpu,visible));File.WriteAllLines(Path.Combine(output,"windows.csv"),summaries);Debug.Log("P9_STAGE capacity-window "+summaries.Last());
